using System;
interface IHinh {
    double DienTich();
}
class Vuong : IHinh {
    double canh;
    public Vuong(double c) { canh = c; }
    public double DienTich() => canh * canh;
}
class Program {
    static void Main() {
        IHinh h = new Vuong(4);
        Console.WriteLine(h.DienTich());
    }
}
